    'Pac-Man'::VARCHAR AS title,
    'replication'::VARCHAR AS label,
    '<p>a top-down 2D maze chase game where the player collects pellets and avoids enemies. The player navigates corridors collecting pellets while avoiding enemies that move through the maze.</p><p>Enemies follow simple behavior patterns like chasing the player, enemies to corners, or making randomized decisions at intersections. Power pellets temporarily make enemies vulnerable so the player can eat them for bonus points before they respawn, and the level ends when all pellets are cleared or the player loses all lives.</p>'::TEXT AS description,
    '[{"name": "index.html", "content": "data/code_files/blank_site/index.html", "language": "html"}, {"name": "styles.css", "content": "data/code_files/blank_site/styles.css", "language": "css"}, {"name": "frontend.js", "content": "data/code_files/blank_site/frontend.js", "language": "javascript"}]'::JSONB AS files,
