  SELECT
    'password_game'::VARCHAR AS name,
    'Password Game'::VARCHAR AS title,
    'replication'::VARCHAR AS label,
    '<p>a puzzle where the player must type a password that satisfies a growing list of rules. Rules are revealed progressively, and the password must satisfy all rules simultaneously as they stack up.</p><p>The fun comes from adjusting the password as new constraints appear, while the UI shows a live pass/fail indicator for every rule and explains what is missing. Players “win” when all rules are satisfied at once, making it feel like a logic juggling act.</p>'::TEXT AS description,
    '[{"name": "index.html", "content": "data/code_files/blank_site/index.html", "language": "html"}, {"name": "styles.css", "content": "data/code_files/blank_site/styles.css", "language": "css"}, {"name": "frontend.js", "content": "data/code_files/blank_site/frontend.js", "language": "javascript"}]'::JSONB AS files,
