    '2050-02-15'::DATE AS voting_end_date UNION ALL
  SELECT
    'zen_garden'::VARCHAR AS name,
    'Zen Garden'::VARCHAR AS title,
    'open-ended'::VARCHAR AS label,
    '<p>Create a relaxing game where players casually place objects and watch a peaceful scene grow over time, with no goals, pressure, or winning.</p>'::TEXT AS description,
    '[{"name": "index.html", "content": "data/code_files/blank_site/index.html", "language": "html"}, {"name": "styles.css", "content": "data/code_files/blank_site/styles.css", "language": "css"}, {"name": "frontend.js", "content": "data/code_files/blank_site/frontend.js", "language": "javascript"}]'::JSONB AS files,
    '2025-01-01'::DATE AS code_start_date,
    '2027-02-08'::DATE AS voting_start_date,
    '2050-02-15'::DATE AS voting_end_date
)

UPDATE projects p
SET
  title = tu.title,
  label = tu.label,
  description = tu.description,
  files = tu.files,
  code_start_date = tu.code_start_date,
  voting_start_date = tu.voting_start_date,
  voting_end_date = tu.voting_end_date,
  updated_at = NOW()
FROM task_updates tu
WHERE p.name = tu.name;

